arguments.content:
{
  "version": "V8",
  "phase": "grading",
  "step": 1,
  "segments": [
    {
      "id": "段1",
      "content": "WLOG排序：通过施加一个置换，不妨设 a₁ < a₂ < ... < aₙ。",
      "features": ["WLOG归约", "排序", "aₙ的最大性"]
    },
    {
      "id": "段2",
      "content": "定义关键变量 x = a₁ + ... + a_{n-1}（除最大元外所有元素之和）。",
      "features": ["定义变量", "x的定义", "aₙ的最大性"]
    },
    {
      "id": "段3",
      "content": "建立证明框架：对 n 施强归纳。",
      "features": ["强归纳假设"]
    },
    {
      "id": "段4",
      "content": "情况分析的总纲：按 M 中元素相对 x 的位置分三种情况。",
      "features": ["情况分析", "x的分类标准角色"]
    },
    {
      "id": "段5",
      "content": "Case 1 条件：x ∈ M 且存在 y ∈ M 满足 y > x；由此推出 n ≥ 3。",
      "features": ["情况分析", "x的分类标准角色", "边界推导"]
    },
    {
      "id": "段6",
      "content": "在 n-1 个小元素中定义'坏'指标 i：x - aᵢ ∈ M 或 s - aᵢ ∈ M。",
      "features": ["定义变量", "bad index的定义", "x的使用", "s的使用"]
    },
    {
      "id": "段7",
      "content": "单射论证：坏指标到 M\\{x} 的映射是单射（x - aᵢ 落入 M\\{x}，s - aᵢ > x 落入 M∩(x,∞)）。",
      "features": ["鸽巢论证", "单射论证", "x的使用", "s的使用", "aₙ的最大性"]
    },
    {
      "id": "段8",
      "content": "鸽巢结论：|M\\{x}| = n-2，故 n-1 个指标中至多 n-2 个坏指标，存在好指标 r 使 x - aᵣ ∉ M 且 s - aᵣ ∉ M。",
      "features": ["鸽巢论证", "good index r的存在性", "x的使用", "s的使用"]
    },
    {
      "id": "段9",
      "content": "令 t = x - aᵣ，构造缩减禁集 M' = M ∩ (-∞, t]。",
      "features": ["定义变量", "t的定义", "M'的构造", "x的使用"]
    },
    {
      "id": "段10",
      "content": "估计 |M'| ≤ n-3（x 和 y 都被排除在 M' 之外）。",
      "features": ["M'的规模估计", "x的使用"]
    },
    {
      "id": "段11",
      "content": "对剩余 n-2 个元素（去掉 aᵣ 和 aₙ）配 M' 施归纳，得到置换 p'。",
      "features": ["归纳应用", "M'的构造", "aₙ的最大性", "good index r的使用"]
    },
    {
      "id": "段12",
      "content": "构造完整置换：先放 p'，再放 aᵣ，再放 aₙ（通过一次 swap 把 aₙ 放到倒数第二位）。",
      "features": ["构造性证明", "swap技巧", "aₙ的最大性", "good index r的使用"]
    },
    {
      "id": "段13",
      "content": "验证：aᵣ 之前的前缀和 ≤ t 且避开 M'；到 aᵣ 的和避开 M（由 r 的选取）；最终和为 s ∉ M。",
      "features": ["验证", "x的使用", "s的使用", "aₙ的最大性", "good index r的使用", "M'的构造"]
    },
    {
      "id": "段14",
      "content": "Case 2 条件：x ∉ M 且存在 y ∈ M 满足 y > x；故 |M ∩ (-∞, x]| ≤ n-2。",
      "features": ["情况分析", "x的分类标准角色", "M'的规模估计"]
    },
    {
      "id": "段15",
      "content": "令 M' = M ∩ (-∞, x]，对 a₁,...,a_{n-1} 配 M' 施归纳（其和为 x ∉ M'）。",
      "features": ["M'的构造", "归纳应用", "x的使用", "aₙ的最大性"]
    },
    {
      "id": "段16",
      "content": "退化处理：若 M' 为空用恒等置换；否则取归纳所得 p'，末尾接 aₙ。",
      "features": ["构造性证明", "退化情况处理", "aₙ的最大性"]
    },
    {
      "id": "段17",
      "content": "验证：前 n-1 跳的前缀和 ≤ x 且避开 M'；最终和为 s ∉ M。",
      "features": ["验证", "x的使用", "s的使用", "aₙ的最大性"]
    },
    {
      "id": "段18",
      "content": "Case 3 条件：所有 m ∈ M 满足 m ≤ x；令 z = max(M)，M' = M\\{z}。",
      "features": ["情况分析", "x的分类标准角色", "定义变量", "z的定义", "M'的构造"]
    },
    {
      "id": "段19",
      "content": "对 a₁,...,a_{n-1} 配 M'（|M'| = n-2）施归纳，得到置换 p'。",
      "features": ["归纳应用", "M'的构造", "aₙ的最大性"]
    },
    {
      "id": "段20",
      "content": "若 p' 的某前缀和在位置 k 处等于 z，则把位置 k 与末位 swap：在位置 k 放 aₙ（因 aₙ > a_{p'(k)} 跳过 z），把 a_{p'(k)} 放末位。",
      "features": ["构造性证明", "swap技巧", "z的使用", "aₙ的最大性"]
    },
    {
      "id": "段21",
      "content": "若无前缀和等于 z，则 p' 已避开全部 M（M = M' ∪ {z} 而 z 从未被命中）。",
      "features": ["验证", "z的使用", "M'的构造"]
    },
    {
      "id": "段22",
      "content": "归约闭合：一般情形（未排序的 a）通过复合排序置换归约到已排序情形。",
      "features": ["WLOG归约", "归约闭合"]
    }
  ]
}
